static int bpf_object__elf_collect(struct bpf_object *obj)
{
        struct elf_sec_desc *sec_desc;
        Elf *elf = obj->efile.elf;
        Elf_Data *btf_ext_data = NULL;
        Elf_Data *btf_data = NULL;
        int idx = 0, err = 0;
        const char *name;
        Elf_Data *data;
        Elf_Scn *scn;
        Elf64_Shdr *sh;

        /* ELF section indices are 1-based, so allocate +1 element to keep
         * indexing simple. Also include 0th invalid section into sec_cnt for
         * simpler and more traditional iteration logic.
         */
        obj->efile.sec_cnt = 1 + obj->efile.ehdr->e_shnum;
        obj->efile.secs = calloc(obj->efile.sec_cnt, sizeof(*obj->efile.secs));
        if (!obj->efile.secs)
                return -ENOMEM;

        /* a bunch of ELF parsing functionality depends on processing symbols,
         * so do the first pass and find the symbol table
         */
        scn = NULL;
        while ((scn = elf_nextscn(elf, scn)) != NULL) {
                sh = elf_sec_hdr(obj, scn);
                if (!sh)
                        return -LIBBPF_ERRNO__FORMAT;

                if (sh->sh_type == SHT_SYMTAB) {
                        if (obj->efile.symbols) {
                                pr_warn("elf: multiple symbol tables in %s\n", obj->path);
                                return -LIBBPF_ERRNO__FORMAT;
                        }

                        data = elf_sec_data(obj, scn);
                        if (!data)
                                return -LIBBPF_ERRNO__FORMAT;

                        idx = elf_ndxscn(scn);

                        obj->efile.symbols = data;
                        obj->efile.symbols_shndx = idx;
                        obj->efile.strtabidx = sh->sh_link;
                }
        }

        if (!obj->efile.symbols) {
                pr_warn("elf: couldn't find symbol table in %s, stripped object file?\n",
                        obj->path);
                return -ENOENT;
        }

        scn = NULL;
        while ((scn = elf_nextscn(elf, scn)) != NULL) {
                idx = elf_ndxscn(scn);
                sec_desc = &obj->efile.secs[idx];

                sh = elf_sec_hdr(obj, scn);
                if (!sh)
                        return -LIBBPF_ERRNO__FORMAT;

                name = elf_sec_str(obj, sh->sh_name);
                if (!name)
                        return -LIBBPF_ERRNO__FORMAT;

                if (ignore_elf_section(sh, name))
                        continue;

                data = elf_sec_data(obj, scn);
                if (!data)
                        return -LIBBPF_ERRNO__FORMAT;

                pr_debug("elf: section(%d) %s, size %ld, link %d, flags %lx, type=%d\n",
                         idx, name, (unsigned long)data->d_size,
                         (int)sh->sh_link, (unsigned long)sh->sh_flags,
                         (int)sh->sh_type);

                if (strcmp(name, "license") == 0) {
                        err = bpf_object__init_license(obj, data->d_buf, data->d_size);
                        if (err)
                                return err;
                } else if (strcmp(name, "version") == 0) {
                        err = bpf_object__init_kversion(obj, data->d_buf, data->d_size);
                        if (err)
                                return err;
                } else if (strcmp(name, "maps") == 0) {
                        obj->efile.maps_shndx = idx;
                } else if (strcmp(name, MAPS_ELF_SEC) == 0) {
                        obj->efile.btf_maps_shndx = idx;
                } else if (strcmp(name, BTF_ELF_SEC) == 0) {
                        btf_data = data;
                } else if (strcmp(name, BTF_EXT_ELF_SEC) == 0) {
                        btf_ext_data = data;
                } else if (sh->sh_type == SHT_SYMTAB) {
                        /* already processed during the first pass above */
                } else if (sh->sh_type == SHT_PROGBITS && data->d_size > 0) {
                        if (sh->sh_flags & SHF_EXECINSTR) {
                                if (strcmp(name, ".text") == 0)
                                        obj->efile.text_shndx = idx;
                                err = bpf_object__add_programs(obj, data, name, idx);
                                if (err)
                                        return err;
                        } else if (strcmp(name, DATA_SEC) == 0 ||
                                   str_has_pfx(name, DATA_SEC ".")) {
                                sec_desc->sec_type = SEC_DATA;
                                sec_desc->shdr = sh;
                                sec_desc->data = data;
                        } else if (strcmp(name, RODATA_SEC) == 0 ||
                                   str_has_pfx(name, RODATA_SEC ".")) {
                                sec_desc->sec_type = SEC_RODATA;
                                sec_desc->shdr = sh;
                                sec_desc->data = data;
                        } else if (strcmp(name, STRUCT_OPS_SEC) == 0) {
                                obj->efile.st_ops_data = data;
                                obj->efile.st_ops_shndx = idx;
                        } else {
                                pr_info("elf: skipping unrecognized data section(%d) %s\n",
                                        idx, name);
                        }
                } else if (sh->sh_type == SHT_REL) {
                        int targ_sec_idx = sh->sh_info; /* points to other section */

                        /* Only do relo for section with exec instructions */
                        if (!section_have_execinstr(obj, targ_sec_idx) &&
                            strcmp(name, ".rel" STRUCT_OPS_SEC) &&
                            strcmp(name, ".rel" MAPS_ELF_SEC)) {
                                pr_info("elf: skipping relo section(%d) %s for section(%d) %s\n",
                                        idx, name, targ_sec_idx,
                                        elf_sec_name(obj, elf_sec_by_idx(obj, targ_sec_idx)) ?: "<?>");
                                continue;
                        }

                        sec_desc->sec_type = SEC_RELO;
                        sec_desc->shdr = sh;
                        sec_desc->data = data;
                } else if (sh->sh_type == SHT_NOBITS && strcmp(name, BSS_SEC) == 0) {
                        sec_desc->sec_type = SEC_BSS;
                        sec_desc->shdr = sh;
                        sec_desc->data = data;
                } else {
                        pr_info("elf: skipping section(%d) %s (size %zu)\n", idx, name,
                                (size_t)sh->sh_size);
                }
        }

        if (!obj->efile.strtabidx || obj->efile.strtabidx > idx) {
                pr_warn("elf: symbol strings section missing or invalid in %s\n", obj->path);
                return -LIBBPF_ERRNO__FORMAT;
        }

        /* sort BPF programs by section name and in-section instruction offset
         * for faster search */
        qsort(obj->programs, obj->nr_programs, sizeof(*obj->programs), cmp_progs);

        return bpf_object__init_btf(obj, btf_data, btf_ext_data);
}

static bool sym_is_extern(const Elf64_Sym *sym)
{
        int bind = ELF64_ST_BIND(sym->st_info);
        /* externs are symbols w/ type=NOTYPE, bind=GLOBAL|WEAK, section=UND */
        return sym->st_shndx == SHN_UNDEF &&
               (bind == STB_GLOBAL || bind == STB_WEAK) &&
               ELF64_ST_TYPE(sym->st_info) == STT_NOTYPE;
}

static bool sym_is_subprog(const Elf64_Sym *sym, int text_shndx)
{
        int bind = ELF64_ST_BIND(sym->st_info);
        int type = ELF64_ST_TYPE(sym->st_info);

        /* in .text section */
        if (sym->st_shndx != text_shndx)
                return false;

        /* local function */
        if (bind == STB_LOCAL && type == STT_SECTION)
                return true;

        /* global function */
        return bind == STB_GLOBAL && type == STT_FUNC;
}

static int find_extern_btf_id(const struct btf *btf, const char *ext_name)
{
        const struct btf_type *t;
        const char *tname;
        int i, n;

        if (!btf)
                return -ESRCH;

        n = btf__type_cnt(btf);
        for (i = 1; i < n; i++) {
                t = btf__type_by_id(btf, i);

---

                if (!btf_is_var(t) && !btf_is_func(t))
                        continue;

                tname = btf__name_by_offset(btf, t->name_off);
                if (strcmp(tname, ext_name))
                        continue;

                if (btf_is_var(t) &&
                    btf_var(t)->linkage != BTF_VAR_GLOBAL_EXTERN)
                        return -EINVAL;

                if (btf_is_func(t) && btf_func_linkage(t) != BTF_FUNC_EXTERN)
                        return -EINVAL;

                return i;
        }

        return -ENOENT;
}

static int find_extern_sec_btf_id(struct btf *btf, int ext_btf_id) {
        const struct btf_var_secinfo *vs;
        const struct btf_type *t;
        int i, j, n;

        if (!btf)
                return -ESRCH;

        n = btf__type_cnt(btf);
        for (i = 1; i < n; i++) {
                t = btf__type_by_id(btf, i);

                if (!btf_is_datasec(t))
                        continue;

                vs = btf_var_secinfos(t);
                for (j = 0; j < btf_vlen(t); j++, vs++) {
                        if (vs->type == ext_btf_id)
                                return i;
                }
        }

        return -ENOENT;
}

static enum kcfg_type find_kcfg_type(const struct btf *btf, int id,
                                     bool *is_signed)
{
        const struct btf_type *t;
        const char *name;

        t = skip_mods_and_typedefs(btf, id, NULL);
        name = btf__name_by_offset(btf, t->name_off);

        if (is_signed)
                *is_signed = false;
        switch (btf_kind(t)) {
        case BTF_KIND_INT: {
                int enc = btf_int_encoding(t);

                if (enc & BTF_INT_BOOL)
                        return t->size == 1 ? KCFG_BOOL : KCFG_UNKNOWN;
                if (is_signed)
                        *is_signed = enc & BTF_INT_SIGNED;
                if (t->size == 1)
                        return KCFG_CHAR;
                if (t->size < 1 || t->size > 8 || (t->size & (t->size - 1)))
                        return KCFG_UNKNOWN;
                return KCFG_INT;
        }
        case BTF_KIND_ENUM:
                if (t->size != 4)
                        return KCFG_UNKNOWN;
                if (strcmp(name, "libbpf_tristate"))
                        return KCFG_UNKNOWN;
                return KCFG_TRISTATE;
        case BTF_KIND_ARRAY:
                if (btf_array(t)->nelems == 0)
                        return KCFG_UNKNOWN;
                if (find_kcfg_type(btf, btf_array(t)->type, NULL) != KCFG_CHAR)
                        return KCFG_UNKNOWN;
                return KCFG_CHAR_ARR;
        default:
                return KCFG_UNKNOWN;
        }
}

static int cmp_externs(const void *_a, const void *_b)
{
        const struct extern_desc *a = _a;
        const struct extern_desc *b = _b;

        if (a->type != b->type)
                return a->type < b->type ? -1 : 1;

        if (a->type == EXT_KCFG) {
                /* descending order by alignment requirements */
                if (a->kcfg.align != b->kcfg.align)
                        return a->kcfg.align > b->kcfg.align ? -1 : 1;
                /* ascending order by size, within same alignment class */
                if (a->kcfg.sz != b->kcfg.sz)
                        return a->kcfg.sz < b->kcfg.sz ? -1 : 1;
        }

        /* resolve ties by name */
        return strcmp(a->name, b->name);
}

static int find_int_btf_id(const struct btf *btf)
{
        const struct btf_type *t;
        int i, n;

        n = btf__type_cnt(btf);
        for (i = 1; i < n; i++) {
                t = btf__type_by_id(btf, i);

                if (btf_is_int(t) && btf_int_bits(t) == 32)
                        return i;
        }

        return 0;
}

static int add_dummy_ksym_var(struct btf *btf)
{
        int i, int_btf_id, sec_btf_id, dummy_var_btf_id;
        const struct btf_var_secinfo *vs;
        const struct btf_type *sec;

        if (!btf)
                return 0;

        sec_btf_id = btf__find_by_name_kind(btf, KSYMS_SEC,
                                            BTF_KIND_DATASEC);
        if (sec_btf_id < 0)
                return 0;

        sec = btf__type_by_id(btf, sec_btf_id);
        vs = btf_var_secinfos(sec);
        for (i = 0; i < btf_vlen(sec); i++, vs++) {
                const struct btf_type *vt;

                vt = btf__type_by_id(btf, vs->type);
                if (btf_is_func(vt))
                        break;
        }

        /* No func in ksyms sec.  No need to add dummy var. */
        if (i == btf_vlen(sec))
                return 0;

        int_btf_id = find_int_btf_id(btf);
        dummy_var_btf_id = btf__add_var(btf,
                                        "dummy_ksym",
                                        BTF_VAR_GLOBAL_ALLOCATED,
                                        int_btf_id);
        if (dummy_var_btf_id < 0)
                pr_warn("cannot create a dummy_ksym var\n");

        return dummy_var_btf_id;
}

